#!/usr/bin/env python3

"""
RoboMaster 哨兵导航与决策系统
第 9 课：血量 + 比赛时间联合决策

本课目标：

让机器人同时根据：

    1. 血量 health
    2. 比赛时间 match_time

进行简单决策。

决策结果：

    GO_TO_POINT
        → 前往得分点

    RETURN_BASE
        → 返回基地

注意：

本课使用的是“教学版决策规则”。

真正比赛策略后面会继续完善。
"""


# =====================================================
# 导入 ROS2
# =====================================================

import rclpy

from rclpy.node import Node


# =====================================================
# 导入消息
# =====================================================

from std_msgs.msg import Int32


# =====================================================
# RobotState
# =====================================================

class RobotState:

    """
    保存机器人当前状态。
    """

    def __init__(self):

        # -------------------------------
        # 血量
        # -------------------------------

        self.health = 100


        # -------------------------------
        # 机器人位置
        # -------------------------------

        self.x = 0.0

        self.y = 0.0


        # -------------------------------
        # 机器人朝向
        # -------------------------------

        self.yaw = 0.0


        # -------------------------------
        # 比赛时间
        # -------------------------------

        self.match_time = 0.0


# =====================================================
# DecisionEngine
# =====================================================

class DecisionEngine:

    """
    DecisionEngine：

    决策引擎。

    输入：

        RobotState

    输出：

        GO_TO_POINT
        RETURN_BASE
    """

    def decide(self, state):

        """
        根据当前 RobotState 做决策。
        """

        # =================================================
        # 第一种情况：
        # 血量低
        # =================================================

        if state.health < 30:

            return "RETURN_BASE"


        # =================================================
        # 第二种情况：
        # 血量正常
        # =================================================

        else:

            return "GO_TO_POINT"


# =====================================================
# DecisionNode
# =====================================================

class DecisionNode(Node):

    """
    ROS2 决策节点。
    """

    def __init__(self):

        # 初始化 ROS2 Node

        super().__init__("health_time_decision_node")


        # =================================================
        # 创建 RobotState
        # =================================================

        self.state = RobotState()


        # =================================================
        # 创建 DecisionEngine
        # =================================================

        self.decision_engine = DecisionEngine()


        # =================================================
        # 订阅血量
        # =================================================

        self.health_subscription = self.create_subscription(

            Int32,

            "/sentinel/health",

            self.health_callback,

            10
        )


        # =================================================
        # Timer
        # =================================================

        # 每秒进行一次决策。

        self.timer = self.create_timer(

            1.0,

            self.run_decision
        )


        # =================================================
        # 启动提示
        # =================================================

        self.get_logger().info(

            "Health + Time Decision Node Start!"
        )


    # =====================================================
    # 血量 Callback
    # =====================================================

    def health_callback(self, msg):

        """
        更新机器人血量。
        """

        self.state.health = msg.data


    # =====================================================
    # 决策函数
    # =====================================================

    def run_decision(self):

        """
        每秒执行一次：

            RobotState
                ↓
            DecisionEngine
                ↓
            Decision
        """

        # ---------------------------------------------
        # 更新时间
        # ---------------------------------------------

        self.state.match_time += 1.0


        # ---------------------------------------------
        # 获取决策
        # ---------------------------------------------

        decision = self.decision_engine.decide(

            self.state
        )


        # ---------------------------------------------
        # 输出当前状态
        # ---------------------------------------------

        self.get_logger().info(

            f"Health = {self.state.health}"
        )


        self.get_logger().info(

            f"Match Time = "
            f"{self.state.match_time:.1f} s"
        )


        self.get_logger().info(

            f"Decision = {decision}"
        )


# =====================================================
# main
# =====================================================

def main(args=None):

    # 初始化 ROS2

    rclpy.init(args=args)


    # 创建节点

    node = DecisionNode()


    # 保持节点运行

    rclpy.spin(node)


    # 关闭 ROS2

    rclpy.shutdown()


# =====================================================
# 程序入口
# =====================================================

if __name__ == "__main__":

    main()